return function(Plasma)
	local create = Plasma.create
	return Plasma.widget(function(children, options)
		options = options or {}
		local style = Plasma.useStyle()

		local refs = Plasma.useInstance(function(ref)

			local frame = create("Frame", {
				[ref] = "rect",
				Name = "Rect",
				Position = UDim2.new(0, 0, 0, 0),
				Size = UDim2.new(1, 0, 0, 0),
				AutomaticSize = Enum.AutomaticSize.Y,
				BackgroundColor3 = style.bg1,
				create("UICorner"),

				create("UIPadding", {
					PaddingBottom = UDim.new(0, 8),
					PaddingLeft = UDim.new(0, 8),
					PaddingRight = UDim.new(0, 8),
					PaddingTop = UDim.new(0, 8),
				}),

				create("UIListLayout", {
					[ref] = "list",
					SortOrder = Enum.SortOrder.LayoutOrder,
					HorizontalAlignment = Enum.HorizontalAlignment.Left,
					Padding = UDim.new(0, 8)
				}),
			})

			ref.frame = frame

			return frame
		end)
		refs.frame.Size = options.Size or UDim2.fromScale(1, 0)
		refs.list.FillDirection = options.FillDirection or Enum.FillDirection.Vertical
		refs.rect.BackgroundColor3 = options.BackgroundColor3 or style.bg1
		Plasma.scope(children)
		return refs.rect
	end)
end
